import java.util.*;
import java.io.*;

public class _1599_C_Variant3 {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        double p = Double.parseDouble(parts[1]);
        int totalComb = getTotalCombinations(n);
        for (int i = 0; i <= n; i++) {
            double prob = 0;
            double p1 = (double) i * twoChoose(n - i) / totalComb;
            double p2 = (double) twoChoose(i) * (n - i) / totalComb;
            double p3 = (double) threeChoose(i) / totalComb;
            prob = p1 / 2 + p2 + p3;
            if (prob >= p) {
                pw.println(i);
                break;
            }
        }
        br.close();
        pw.close();
    }

    static int twoChoose(int n) {
        if (n < 2) return 0;
        return n * (n - 1) / 2;
    }

    static int threeChoose(int n) {
        if (n < 3) return 0;
        return n * (n - 1) * (n - 2) / 6;
    }

    static int getTotalCombinations(int n) {
        return threeChoose(n);
    }
}
